(function(){
  var SERVICES = [
    { id: 'raf-tablo-montaji', name: 'Raf & Tablo Montajı' },
    { id: 'musluk-degisimi', name: 'Musluk Değişimi' },
    { id: 'tek-oda-boya', name: 'Tek Oda Boyama' },
    { id: 'kornis-perde-montaji', name: 'Korniş & Perde Montajı' },
    { id: 'avize-montaji', name: 'Avize Montajı' },
    { id: 'ev-temizligi', name: 'Ev Temizliği' }
  ];

  var lastTriggerBtn = null;
  var handoffModal = null;
  var activeJob = {
    jobIndex: -1,
    serviceId: SERVICES[0].id,
    referenceWorkId: 'work-1',
    referenceKind: 'inspiration',
    targetProfessionalId: null,
    answers: { itemCount: '1–2 parça' },
    imgSrc: '',
    imgAlt: '',
    hasReference: true
  };

  document.addEventListener('click', function(e){
    var btn = e.target && e.target.closest ? e.target.closest('.work-btn') : null;
    if(btn) lastTriggerBtn = btn;
  }, true);

  var origOpenWorkModal = window.openWorkModal;
  window.openWorkModal = function(title, meta){
    if(typeof origOpenWorkModal === 'function'){
      try { origOpenWorkModal.apply(this, arguments); } catch(err){}
    }
    setupFlowDetail(title, meta);
  };

  function setupFlowDetail(title, meta){
    var workModal = document.getElementById('work-modal');
    if(!workModal) return;

    var card = lastTriggerBtn ? lastTriggerBtn.closest('.work-card') : null;
    if(!card && title){
      var cards = document.querySelectorAll('.works-grid .work-card');
      for(var i = 0; i < cards.length; i++){
        var h3 = cards[i].querySelector('.work-meta h3');
        if(h3 && h3.textContent.trim() === title.trim()){
          card = cards[i];
          break;
        }
      }
    }
    var cardsList = Array.prototype.slice.call(document.querySelectorAll('.works-grid .work-card'));
    var idx = card ? cardsList.indexOf(card) : 0;
    if(idx < 0 || idx >= SERVICES.length) idx = 0;

    var service = SERVICES[idx];
    var imgEl = card ? card.querySelector('.work-btn img') : null;
    var imgSrc = imgEl ? (imgEl.getAttribute('src') || '') : '';
    var imgAlt = imgEl ? (imgEl.getAttribute('alt') || service.name) : service.name;

    if(activeJob.jobIndex !== idx){
      activeJob.jobIndex = idx;
      activeJob.serviceId = service.id;
      activeJob.referenceWorkId = 'work-' + (idx + 1);
      activeJob.referenceKind = 'inspiration';
      activeJob.targetProfessionalId = null;
      activeJob.answers = (service.id === 'raf-tablo-montaji') ? { itemCount: '1–2 parça' } : {};
      activeJob.imgSrc = imgSrc;
      activeJob.imgAlt = imgAlt;
      activeJob.hasReference = true;
    } else {
      if(!activeJob.imgSrc && imgSrc) activeJob.imgSrc = imgSrc;
      if(!activeJob.imgAlt && imgAlt) activeJob.imgAlt = imgAlt;
    }

    var detail = workModal.querySelector('.flow-detail');
    if(!detail){
      detail = document.createElement('div');
      detail.className = 'flow-detail';
      workModal.appendChild(detail);
    }
    while(detail.firstChild){
      detail.removeChild(detail.firstChild);
    }

    var grid = document.createElement('div');
    grid.className = 'flow-detail-grid';

    var mediaCol = document.createElement('div');
    mediaCol.className = 'flow-detail-media';
    if(activeJob.imgSrc){
      var dImg = document.createElement('img');
      dImg.className = 'flow-detail-img';
      dImg.src = activeJob.imgSrc;
      dImg.alt = activeJob.imgAlt || service.name;
      mediaCol.appendChild(dImg);
    }
    var badge = document.createElement('span');
    badge.className = 'flow-badge';
    badge.textContent = 'Temsili uygulama ve uzman görseli';
    mediaCol.appendChild(badge);

    var scopeCol = document.createElement('div');
    scopeCol.className = 'flow-detail-scope';

    var tag = document.createElement('p');
    tag.className = 'flow-service-tag';
    tag.textContent = 'Hizmet: ' + service.name;

    var titleEl = document.createElement('h4');
    titleEl.className = 'flow-scope-title';
    titleEl.textContent = 'Talep Kapsamınızı Belirleyin';

    var descEl = document.createElement('p');
    descEl.className = 'flow-scope-desc';
    descEl.textContent = 'Bu çalışmayı ilham alarak ustanıza iletmek istediğiniz kapsamı belirleyin. Hangi alanda ve nasıl bir uygulama planlıyorsunuz? İstediğiniz parça sayısı veya montaj detaylarını sihirbazda belirtebilirsiniz. Kesin malzeme gereksinimleri, süre ve fiyatlandırma talebiniz incelendikten sonra netleşir.';

    var actions = document.createElement('div');
    actions.className = 'flow-actions';

    var startBtn = document.createElement('button');
    startBtn.type = 'button';
    startBtn.className = 'flow-btn-primary flow-btn-start';
    startBtn.textContent = 'Benzerini yaptır';
    startBtn.addEventListener('click', function(){
      workModal.close();
      openHandoffModal();
    });

    var closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'flow-btn-neutral flow-btn-close';
    closeBtn.textContent = 'Kapat';
    closeBtn.addEventListener('click', function(){
      workModal.close();
    });

    actions.appendChild(startBtn);
    actions.appendChild(closeBtn);

    scopeCol.appendChild(tag);
    scopeCol.appendChild(titleEl);
    scopeCol.appendChild(descEl);
    scopeCol.appendChild(actions);

    grid.appendChild(mediaCol);
    grid.appendChild(scopeCol);
    detail.appendChild(grid);
  }

  function ensureHandoffModal(){
    if(handoffModal) return handoffModal;
    handoffModal = document.getElementById('handoff');
    if(!handoffModal){
      handoffModal = document.createElement('dialog');
      handoffModal.id = 'handoff';
      document.body.appendChild(handoffModal);
    }
    handoffModal.addEventListener('keydown', function(e){
      if(e.key === 'Escape'){
        e.preventDefault();
        handoffModal.close();
        if(lastTriggerBtn && typeof lastTriggerBtn.focus === 'function'){
          lastTriggerBtn.focus();
        }
      }
    });
    handoffModal.addEventListener('cancel', function(e){
      e.preventDefault();
      handoffModal.close();
      if(lastTriggerBtn && typeof lastTriggerBtn.focus === 'function'){
        lastTriggerBtn.focus();
      }
    });
    return handoffModal;
  }

  function openHandoffModal(){
    var modal = ensureHandoffModal();
    renderHandoffModal(modal);
    modal.showModal();
  }

  function renderHandoffModal(modal){
    while(modal.firstChild){
      modal.removeChild(modal.firstChild);
    }

    var liveStatus = document.createElement('div');
    liveStatus.id = 'flow-handoff-status';
    liveStatus.className = 'flow-sr-only';
    liveStatus.setAttribute('aria-live', 'polite');
    liveStatus.setAttribute('role', 'status');
    modal.appendChild(liveStatus);

    function updateLive(msg){
      liveStatus.textContent = msg;
    }

    var banner = document.createElement('div');
    banner.className = 'flow-handoff-banner';
    banner.setAttribute('role', 'note');
    banner.textContent = 'Wizard giriş önizlemesi · Talep gönderilmez';
    modal.appendChild(banner);

    var header = document.createElement('div');
    header.className = 'flow-handoff-header';
    var hTitle = document.createElement('h3');
    hTitle.className = 'flow-handoff-title';
    hTitle.textContent = 'Talep Giriş Önizlemesi';
    var hClose = document.createElement('button');
    hClose.type = 'button';
    hClose.className = 'flow-btn-neutral';
    hClose.setAttribute('aria-label', 'Pencereyi kapat');
    hClose.textContent = '✕';
    hClose.addEventListener('click', function(){
      modal.close();
      if(lastTriggerBtn && typeof lastTriggerBtn.focus === 'function'){
        lastTriggerBtn.focus();
      }
    });
    header.appendChild(hTitle);
    header.appendChild(hClose);
    modal.appendChild(header);

    var secService = document.createElement('div');
    secService.className = 'flow-section';
    var sLabel = document.createElement('label');
    sLabel.className = 'flow-label';
    sLabel.htmlFor = 'flow-service-select';
    sLabel.textContent = 'Seçili Hizmet';
    var select = document.createElement('select');
    select.id = 'flow-service-select';
    select.className = 'flow-select';
    for(var i = 0; i < SERVICES.length; i++){
      var opt = document.createElement('option');
      opt.value = SERVICES[i].id;
      opt.textContent = SERVICES[i].name;
      if(SERVICES[i].id === activeJob.serviceId) opt.selected = true;
      select.appendChild(opt);
    }
    secService.appendChild(sLabel);
    secService.appendChild(select);
    modal.appendChild(secService);

    var secRef = document.createElement('div');
    secRef.className = 'flow-section';
    var refLabel = document.createElement('span');
    refLabel.className = 'flow-label';
    refLabel.textContent = 'İlham Referansı (Opsiyonel)';
    secRef.appendChild(refLabel);
    var refCardContainer = document.createElement('div');
    secRef.appendChild(refCardContainer);
    modal.appendChild(secRef);

    function updateRefCard(){
      while(refCardContainer.firstChild){
        refCardContainer.removeChild(refCardContainer.firstChild);
      }
      if(activeJob.hasReference && activeJob.referenceWorkId && activeJob.imgSrc){
        var card = document.createElement('div');
        card.className = 'flow-ref-card';
        var thumb = document.createElement('img');
        thumb.className = 'flow-ref-thumb';
        thumb.src = activeJob.imgSrc;
        thumb.alt = activeJob.imgAlt || 'Referans görseli';
        var body = document.createElement('div');
        body.className = 'flow-ref-body';
        var kind = document.createElement('span');
        kind.className = 'flow-ref-kind';
        kind.textContent = 'Katalog İlham Referansı';
        var hint = document.createElement('span');
        hint.className = 'flow-ref-hint';
        hint.textContent = 'Bu görsel ustanıza referans olarak aktarılır (kullanıcı yüklemesi değildir).';
        var rmBtn = document.createElement('button');
        rmBtn.type = 'button';
        rmBtn.className = 'flow-btn-remove';
        rmBtn.setAttribute('aria-label', 'Görsel referansını kaldır');
        rmBtn.textContent = 'Görseli kaldır';
        rmBtn.addEventListener('click', function(){
          activeJob.hasReference = false;
          activeJob.referenceWorkId = null;
          activeJob.referenceKind = null;
          updateLive('Görsel referansı kaldırıldı.');
          updateRefCard();
          updatePayload();
        });
        body.appendChild(kind);
        body.appendChild(hint);
        body.appendChild(rmBtn);
        card.appendChild(thumb);
        card.appendChild(body);
        refCardContainer.appendChild(card);
      } else {
        var empty = document.createElement('div');
        empty.className = 'flow-ref-empty';
        empty.textContent = 'Görsel referansı bulunmuyor. Referans olmadan da talebinize devam edebilirsiniz.';
        refCardContainer.appendChild(empty);
      }
    }
    updateRefCard();

    var secQ = document.createElement('div');
    secQ.className = 'flow-section';
    modal.appendChild(secQ);

    function updateQuestions(){
      while(secQ.firstChild){
        secQ.removeChild(secQ.firstChild);
      }
      if(activeJob.serviceId === 'raf-tablo-montaji'){
        var fs = document.createElement('fieldset');
        fs.className = 'flow-fieldset';
        var leg = document.createElement('legend');
        leg.className = 'flow-legend';
        leg.textContent = 'Kaç parça raf, ayna veya tablo asılacak?';
        fs.appendChild(leg);

        var rGroup = document.createElement('div');
        rGroup.className = 'flow-radio-group';
        var opts = ['1–2 parça', '3–5 parça', '6 ve üzeri parça'];
        var currentAns = activeJob.answers.itemCount || '1–2 parça';
        activeJob.answers.itemCount = currentAns;

        for(var k = 0; k < opts.length; k++){
          (function(val){
            var rLabel = document.createElement('label');
            rLabel.className = 'flow-radio-label';
            var radio = document.createElement('input');
            radio.type = 'radio';
            radio.name = 'flow-shelf-answer';
            radio.className = 'flow-radio-input';
            radio.value = val;
            if(val === currentAns) radio.checked = true;
            radio.addEventListener('change', function(){
              activeJob.answers.itemCount = val;
              updatePayload();
            });
            var span = document.createElement('span');
            span.textContent = val;
            rLabel.appendChild(radio);
            rLabel.appendChild(span);
            rGroup.appendChild(rLabel);
          })(opts[k]);
        }
        fs.appendChild(rGroup);
        secQ.appendChild(fs);
      } else {
        var notice = document.createElement('div');
        notice.className = 'flow-notice-box';
        notice.textContent = 'Bu hizmete ait sorular gerçek talep sihirbazında açılır.';
        secQ.appendChild(notice);
      }
    }
    updateQuestions();

    select.addEventListener('change', function(e){
      var newId = e.target.value;
      activeJob.serviceId = newId;
      if(activeJob.hasReference){
        activeJob.hasReference = false;
        activeJob.referenceWorkId = null;
        activeJob.referenceKind = null;
        updateLive('Farklı bir hizmet seçildiği için görsel referansı kaldırıldı.');
      }
      if(newId === 'raf-tablo-montaji' && !activeJob.answers.itemCount){
        activeJob.answers.itemCount = '1–2 parça';
      }
      updateRefCard();
      updateQuestions();
      updatePayload();
    });

    var secActions = document.createElement('div');
    secActions.className = 'flow-actions';

    var inspectBtn = document.createElement('button');
    inspectBtn.type = 'button';
    inspectBtn.className = 'flow-btn-primary';
    inspectBtn.textContent = 'Aktarım bilgisini incele';

    var backBtn = document.createElement('button');
    backBtn.type = 'button';
    backBtn.className = 'flow-btn-neutral';
    backBtn.textContent = '← Detaya geri dön';
    backBtn.addEventListener('click', function(){
      modal.close();
      var workModal = document.getElementById('work-modal');
      if(workModal){
        setupFlowDetail();
        workModal.showModal();
      }
    });

    secActions.appendChild(inspectBtn);
    secActions.appendChild(backBtn);
    modal.appendChild(secActions);

    var pre = document.createElement('pre');
    pre.className = 'flow-pre';
    pre.setAttribute('tabindex', '0');
    pre.setAttribute('aria-label', 'Aktarım verisi');
    modal.appendChild(pre);

    function updatePayload(){
      var payload = {
        serviceId: activeJob.serviceId,
        referenceWorkId: activeJob.hasReference ? activeJob.referenceWorkId : null,
        referenceKind: activeJob.hasReference ? 'inspiration' : null,
        targetProfessionalId: null,
        answers: activeJob.serviceId === 'raf-tablo-montaji' ? activeJob.answers : {}
      };
      pre.textContent = JSON.stringify(payload, null, 2);
    }
    updatePayload();

    inspectBtn.addEventListener('click', function(){
      updatePayload();
      updateLive('Aktarım bilgisi güncellendi.');
    });
  }
})();
